/**
 * A key number with its label and direction of change (`design/components/stat.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/stat.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import {
  Icon,
  MEMBER_PROVIDERS,
  derived,
  useMember,
  type IconProps,
  type IconRole,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/stat.module.css'
import { Badge, type BadgeProps } from './Badge'
import { Sparkline, type SparklineProps } from '../charts/Sparkline'

export type DeltaDirection = 'up' | 'down'

export interface StatDelta {
  value: string
  direction: DeltaDirection
  positive?: boolean
}

export interface StatTrend {
  direction: DeltaDirection
  label: string
}

export interface StatFooter {
  primary: string
  secondary: string
}

/** A key number with its label and direction of change: the inputs it takes, by the React member's prop names. */
export interface StatProps {
  delta?: StatDelta
  /**
   * Shown when there is no delta, such as "vs last week".
   */
  description?: string
  /**
   * The two-line footer: the interpretation, then the period it covers.
   */
  footer?: StatFooter
  icon?: IconRole
  label: string
  /**
   * Tabular figures, so a column of these lines up.
   */
  numeric?: boolean
  /**
   * The trend as a shape: a `Sparkline` at the value row's inline end. It can sit beside `trend`
   * (words for the direction, a shape for the path) and replaces neither `delta` nor `footer`.
   * `Sparkline` draws it, and renders nothing for fewer than two points.
   */
  spark?: readonly number[]
  /**
   * The sparkline's accessible name, as a function of the stat's label because the wording
   * belongs to the catalog; the default is `{label}, recent trend`.
   */
  sparkLabel?: (label: string) => string
  /**
   * The neutral movement chip, top-right. See `StatTrend` for why it is not `delta`.
   */
  trend?: StatTrend
  /**
   * Already formatted by the app.
   */
  value: string
}

/** A key number with its label and direction of change. */
@Component({
  selector: 'pm-stat',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Badge, Icon, Sparkline],
  // prettier-ignore
  template: `<!-- stat -->
<div
[attr.class]="e1()"
data-member="stat"
><!-- labelRow -->
<div
[attr.class]="e2()"
><!-- label -->
<span
[attr.class]="e3()"
>{{ e4() }}</span>
@if (e5()) {<!-- labelEnd -->
<span
[attr.class]="e6()"
>@if (e7()) {<!-- glyph -->
<span
[attr.class]="e8()"
><pm-icon
[name]="e9()"
></pm-icon></span>}
@if (e10()) {<pm-badge
variant="outline"
[icon]="e11()"
>{{ e12() }}</pm-badge>}</span>}</div>
<!-- valueRow -->
<div
[attr.class]="e13()"
><!-- value -->
<span
[attr.class]="e14()"
[attr.data-numeric]="e15()"
>{{ e16() }}</span>
@if (e17()) {<!-- spark -->
<span
[attr.class]="e18()"
><pm-sparkline
[data]="e19()"
[label]="e20()"
></pm-sparkline></span>}</div>
@if (e21()) {<!-- delta -->
<span
[attr.class]="e22()"
[attr.data-direction]="e23()"
[attr.data-positive]="e24()"
><pm-icon
[name]="e25()"
size="sm"
></pm-icon>
<span
aria-hidden="true"
>{{ e26() }}</span>
<!-- spoken -->
<span
[attr.class]="e27()"
>{{ e28() }}</span></span>} @else if (e29()) {<!-- description -->
<span
[attr.class]="e30()"
>{{ e31() }}</span>}
@if (e32()) {<!-- footer -->
<div
[attr.class]="e33()"
><!-- footerPrimary -->
<span
[attr.class]="e34()"
>{{ e35() }}@if (e36()) {<!-- footerGlyph -->
<span
[attr.class]="e37()"
><pm-icon
[name]="e38()"
size="sm"
></pm-icon></span>}</span>
<!-- footerSecondary -->
<span
[attr.class]="e39()"
>{{ e40() }}</span></div>}</div>`,
})
export class Stat {
  readonly delta = input<StatProps['delta']>(undefined)
  /**
   * Shown when there is no delta, such as "vs last week".
   */
  readonly description = input<StatProps['description']>(undefined)
  /**
   * The two-line footer: the interpretation, then the period it covers.
   */
  readonly footer = input<StatProps['footer']>(undefined)
  readonly icon = input<StatProps['icon']>(undefined)
  readonly label = input.required<StatProps['label']>()
  /**
   * Tabular figures, so a column of these lines up.
   */
  readonly numeric = input<Exclude<StatProps['numeric'], undefined>, StatProps['numeric']>(true, {
    transform: (value: StatProps['numeric']) => (value === undefined ? true : value),
  })
  /**
   * The trend as a shape: a `Sparkline` at the value row's inline end. It can sit beside `trend`
   * (words for the direction, a shape for the path) and replaces neither `delta` nor `footer`.
   * `Sparkline` draws it, and renders nothing for fewer than two points.
   */
  readonly spark = input<StatProps['spark']>(undefined)
  /**
   * The sparkline's accessible name, as a function of the stat's label because the wording
   * belongs to the catalog; the default is `{label}, recent trend`.
   */
  readonly sparkLabel = input<Exclude<StatProps['sparkLabel'], undefined>, StatProps['sparkLabel']>(
    (label: string) => `${label}, recent trend`,
    {
      transform: (value: StatProps['sparkLabel']) =>
        value === undefined ? (label: string) => `${label}, recent trend` : value,
    },
  )
  /**
   * The neutral movement chip, top-right. See `StatTrend` for why it is not `delta`.
   */
  readonly trend = input<StatProps['trend']>(undefined)
  /**
   * Already formatted by the app.
   */
  readonly value = input.required<StatProps['value']>()
  protected readonly $ = useMember({
    events: [],
    props: {
      delta: () => this.delta(),
      description: () => this.description(),
      footer: () => this.footer(),
      icon: () => this.icon(),
      label: () => this.label(),
      numeric: () => this.numeric(),
      spark: () => this.spark(),
      sparkLabel: () => this.sparkLabel(),
      trend: () => this.trend(),
      value: () => this.value(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly positive = derived(() =>
    this.$p.delta === undefined
      ? undefined
      : (this.$p.delta.positive ?? this.$p.delta.direction === 'up'),
  )

  protected e1() {
    return styles.stat
  }

  protected e2() {
    return styles.labelRow
  }

  protected e3() {
    return styles.label
  }

  protected e4() {
    return this.$p.label
  }

  protected e5() {
    return this.$p.icon !== undefined || this.$p.trend !== undefined
  }

  protected e6() {
    if (!(this.$p.icon !== undefined || this.$p.trend !== undefined)) return undefined as never
    return styles.labelEnd
  }

  protected e7() {
    if (!(this.$p.icon !== undefined || this.$p.trend !== undefined)) return undefined as never
    return this.$p.icon !== undefined
  }

  protected e8() {
    if (!(this.$p.icon !== undefined || this.$p.trend !== undefined)) return undefined as never
    if (!(this.$p.icon !== undefined)) return undefined as never
    return styles.glyph
  }

  protected e9(): IconProps['name'] {
    if (!(this.$p.icon !== undefined || this.$p.trend !== undefined)) return undefined as never
    if (!(this.$p.icon !== undefined)) return undefined as never
    return this.$p.icon
  }

  protected e10() {
    if (!(this.$p.icon !== undefined || this.$p.trend !== undefined)) return undefined as never
    return this.$p.trend !== undefined
  }

  protected e11(): BadgeProps['icon'] {
    if (!(this.$p.icon !== undefined || this.$p.trend !== undefined)) return undefined as never
    if (!(this.$p.trend !== undefined)) return undefined as never
    return this.$p.trend.direction
  }

  protected e12() {
    if (!(this.$p.icon !== undefined || this.$p.trend !== undefined)) return undefined as never
    if (!(this.$p.trend !== undefined)) return undefined as never
    return this.$p.trend.label
  }

  protected e13() {
    return styles.valueRow
  }

  protected e14() {
    return styles.value
  }

  protected e15() {
    return this.$p.numeric ? '' : undefined
  }

  protected e16() {
    return this.$p.value
  }

  protected e17() {
    return this.$p.spark !== undefined
  }

  protected e18() {
    if (!(this.$p.spark !== undefined)) return undefined as never
    return styles.spark
  }

  protected e19(): SparklineProps['data'] {
    if (!(this.$p.spark !== undefined)) return undefined as never
    return this.$p.spark
  }

  protected e20(): SparklineProps['label'] {
    if (!(this.$p.spark !== undefined)) return undefined as never
    return this.$p.sparkLabel(this.$p.label)
  }

  protected e21() {
    return this.$p.delta !== undefined
  }

  protected e22() {
    if (!(this.$p.delta !== undefined)) return undefined as never
    return styles.delta
  }

  protected e23() {
    if (!(this.$p.delta !== undefined)) return undefined as never
    return this.$p.delta.direction
  }

  protected e24() {
    if (!(this.$p.delta !== undefined)) return undefined as never
    return this.positive.value ? '' : undefined
  }

  protected e25(): IconProps['name'] {
    if (!(this.$p.delta !== undefined)) return undefined as never
    return this.$p.delta.direction
  }

  protected e26() {
    if (!(this.$p.delta !== undefined)) return undefined as never
    return this.$p.delta.value
  }

  protected e27() {
    if (!(this.$p.delta !== undefined)) return undefined as never
    return styles.spoken
  }

  protected e28() {
    if (!(this.$p.delta !== undefined)) return undefined as never
    return `${this.$p.delta.direction} ${this.$p.delta.value} — ${this.positive.value ? 'positive' : 'negative'}`
  }

  protected e29() {
    if (this.$p.delta !== undefined) return undefined as never
    return this.$p.description !== undefined
  }

  protected e30() {
    if (this.$p.delta !== undefined) return undefined as never
    if (!(this.$p.description !== undefined)) return undefined as never
    return styles.description
  }

  protected e31() {
    if (this.$p.delta !== undefined) return undefined as never
    if (!(this.$p.description !== undefined)) return undefined as never
    return this.$p.description
  }

  protected e32() {
    return this.$p.footer !== undefined
  }

  protected e33() {
    if (!(this.$p.footer !== undefined)) return undefined as never
    return styles.footer
  }

  protected e34() {
    if (!(this.$p.footer !== undefined)) return undefined as never
    return styles.footerPrimary
  }

  protected e35() {
    if (!(this.$p.footer !== undefined)) return undefined as never
    return this.$p.footer.primary
  }

  protected e36() {
    if (!(this.$p.footer !== undefined)) return undefined as never
    return this.$p.trend !== undefined
  }

  protected e37() {
    if (!(this.$p.footer !== undefined)) return undefined as never
    if (!(this.$p.trend !== undefined)) return undefined as never
    return styles.footerGlyph
  }

  protected e38(): IconProps['name'] {
    if (!(this.$p.footer !== undefined)) return undefined as never
    if (!(this.$p.trend !== undefined)) return undefined as never
    return this.$p.trend.direction
  }

  protected e39() {
    if (!(this.$p.footer !== undefined)) return undefined as never
    return styles.footerSecondary
  }

  protected e40() {
    if (!(this.$p.footer !== undefined)) return undefined as never
    return this.$p.footer.secondary
  }
}
